INSERT INTO match_player_reports VALUES(24,148,'GK','GK — 후방 최종 방어','오픈플레이 실점 0. 선방 4회(페페 근거리·아요세·부차난 1대1). goals prevented +0.91.','90'' 평점 8.3 · 선방 4 · 터치 40 · 툴x 50.6. 두 실점은 모두 PK다.','gk_goalkeeper/Defend .957 — ATM에서 가장 안정적인 슬롯. 경기 후 라커룸에 단결을 요구했다.','SofaScore API event 16416302 · 원문 reports/match-watch/2026-08-23-atm-villarreal.md · D+1 서사: El Desmarque · Cuatro Picas · Nostresport · Demócrata/COPE · Infobae/EFE · Starnews·스포츠경향(한국어) · bold.dk(덴마크어) · Pulse Sports Nigeria · Into the Calderón/VAVEL(403·요약만) · 시메오네·이니고 페레스 회견','⚠️ 표본 2경기 · 76~90분 10명 경기 · PPDA 미수집 · R1/R2 원천 상이(Opta/SofaScore). ⚠️⚠️ 결과(2-2)와 내용(xG 0.78 대 3.60)의 괴리가 커 결과 기반 판단 금지.');
INSERT INTO match_player_reports VALUES(24,166,'RB','RB(툴x 81.1) — 우측 전진 풀백','수비·공격 양쪽에서 결정적. 미카우타제의 확실한 골을 걷어냈다.','66'' 평점 8.1 · **1골**(59분 박스 밖 왼발 감아차기 상단 구석) · 태클 1 · 터치 43. El Desmarque 8.','fb_wingback/Balanced .853. ⚠️ 그가 66분에 나간 직후 PK로 동점을 허용한 시퀀스는 재검증 대상.','SofaScore API event 16416302 · 원문 reports/match-watch/2026-08-23-atm-villarreal.md · D+1 서사: El Desmarque · Cuatro Picas · Nostresport · Demócrata/COPE · Infobae/EFE · Starnews·스포츠경향(한국어) · bold.dk(덴마크어) · Pulse Sports Nigeria · Into the Calderón/VAVEL(403·요약만) · 시메오네·이니고 페레스 회견','⚠️ 표본 2경기 · 76~90분 10명 경기 · PPDA 미수집 · R1/R2 원천 상이(Opta/SofaScore). ⚠️⚠️ 결과(2-2)와 내용(xG 0.78 대 3.60)의 괴리가 커 결과 기반 판단 금지.');
INSERT INTO match_player_reports VALUES(24,150,'RCB','RCB — 전진한 라인의 뒤를 감당하지 못함','전진 라인 뒤 회복(백트래킹)이 이 경기 최대 약점. 미카우타제가 반복적으로 이용했다.','76'' 평점 5.6 · 🟥 **DOGSO 퇴장**(두 손으로 미카우타제를 뒤에서 밀어 넘어뜨림, VAR 온필드 리뷰) · El Desmarque **2**(팀 최저).','cb_bpd/Aggressive .907 — ⚠️ 적합도는 높으나 이 경기 수행이 적합을 배신했다. 징계는 08-25 Comité 발표 예정(미확정).','SofaScore API event 16416302 · 원문 reports/match-watch/2026-08-23-atm-villarreal.md · D+1 서사: El Desmarque · Cuatro Picas · Nostresport · Demócrata/COPE · Infobae/EFE · Starnews·스포츠경향(한국어) · bold.dk(덴마크어) · Pulse Sports Nigeria · Into the Calderón/VAVEL(403·요약만) · 시메오네·이니고 페레스 회견','⚠️ 표본 2경기 · 76~90분 10명 경기 · PPDA 미수집 · R1/R2 원천 상이(Opta/SofaScore). ⚠️⚠️ 결과(2-2)와 내용(xG 0.78 대 3.60)의 괴리가 커 결과 기반 판단 금지.');
